import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_nchw_f32(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 C_out,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 has_bias
)
{
    .reg .pred  %p<16>;
    .reg .b32   %r<128>;
    .reg .b64   %rd<128>;
    .reg .f32   %f<8>;

    // Load pointers
    ld.param.u64 %rd10, [x_ptr];
    ld.param.u64 %rd11, [w_ptr];
    ld.param.u64 %rd12, [b_ptr];
    ld.param.u64 %rd13, [y_ptr];

    // Load scalar params
    ld.param.u32 %r10, [N];
    ld.param.u32 %r11, [C_in];
    ld.param.u32 %r12, [H_in];
    ld.param.u32 %r13, [W_in];
    ld.param.u32 %r14, [C_out];
    ld.param.u32 %r15, [kH];
    ld.param.u32 %r16, [kW];
    ld.param.u32 %r17, [stride_h];
    ld.param.u32 %r18, [stride_w];
    ld.param.u32 %r19, [pad_h];
    ld.param.u32 %r20, [pad_w];
    ld.param.u32 %r21, [dil_h];
    ld.param.u32 %r22, [dil_w];
    ld.param.u32 %r23, [H_out];
    ld.param.u32 %r24, [W_out];
    ld.param.u32 %r25, [has_bias];

    // Thread id
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mad.lo.s32 %r3, %r1, %r2, %r0; // r3 = global thread id

    // Compute total elements = N * C_out * H_out * W_out (u64)
    cvt.u64.u32 %rd20, %r10;      // N
    cvt.u64.u32 %rd21, %r14;      // C_out
    cvt.u64.u32 %rd22, %r23;      // H_out
    cvt.u64.u32 %rd23, %r24;      // W_out
    mul.lo.u64  %rd24, %rd20, %rd21;   // N*C_out
    mul.lo.u64  %rd25, %rd22, %rd23;   // H_out*W_out
    mul.lo.u64  %rd26, %rd24, %rd25;   // total

    cvt.u64.u32 %rd27, %r3;
    setp.ge.u64 %p0, %rd27, %rd26;
    @%p0 bra DONE;

    // Precompute products for index decomposition (u32)
    mul.lo.u32 %r30, %r23, %r24;      // HW = H_out * W_out
    mul.lo.u32 %r31, %r14, %r30;      // OC_HW = C_out * HW

    // Decompose linear index into (n, oc, y, x)
    // n = tid / OC_HW
    div.u32 %r32, %r3, %r31;          // n
    rem.u32 %r33, %r3, %r31;          // rem1
    div.u32 %r34, %r33, %r30;         // oc
    rem.u32 %r35, %r33, %r30;         // rem2
    div.u32 %r36, %r35, %r24;         // y
    rem.u32 %r37, %r35, %r24;         // x

    // Compute output element address
    cvt.u64.u32 %rd30, %r32;          // n
    cvt.u64.u32 %rd31, %r34;          // oc
    cvt.u64.u32 %rd32, %r36;          // y
    cvt.u64.u32 %rd33, %r37;          // x
    // Convert dims to u64
    cvt.u64.u32 %rd34, %r14;          // C_out
    cvt.u64.u32 %rd35, %r23;          // H_out
    cvt.u64.u32 %rd36, %r24;          // W_out

    mul.lo.u64  %rd37, %rd30, %rd34;          // n*C_out
    add.u64     %rd37, %rd37, %rd31;          // + oc
    mul.lo.u64  %rd37, %rd37, %rd35;          // * H_out
    add.u64     %rd37, %rd37, %rd32;          // + y
    mul.lo.u64  %rd37, %rd37, %rd36;          // * W_out
    add.u64     %rd37, %rd37, %rd33;          // + x
    mul.lo.u64  %rd38, %rd37, 4;              // byte offset
    add.u64     %rd39, %rd13, %rd38;          // y_ptr + offset

    // Prepare constants and s32 versions for bounds
    cvt.s32.u32 %r40, %r12;   // H_in s32
    cvt.s32.u32 %r41, %r13;   // W_in s32

    // y_strided = y * stride_h ; x_strided = x * stride_w
    mul.lo.s32 %r42, %r36, %r17;  // y_strided
    mul.lo.s32 %r43, %r37, %r18;  // x_strided

    // Initialize accumulator with bias if present
    setp.eq.u32 %p1, %r25, 0;
    @%p1 bra NO_BIAS;
    cvt.u64.u32 %rd40, %r34;       // oc
    mul.lo.u64  %rd41, %rd40, 4;
    add.u64     %rd42, %rd12, %rd41;
    ld.global.f32 %f0, [%rd42];
    bra BIAS_DONE;
NO_BIAS:
    mov.f32 %f0, 0f00000000;
BIAS_DONE:

    // Convert more dims to u64 for addressing
    cvt.u64.u32 %rd50, %r11;   // C_in
    cvt.u64.u32 %rd51, %r12;   // H_in
    cvt.u64.u32 %rd52, %r13;   // W_in
    cvt.u64.u32 %rd53, %r15;   // kH
    cvt.u64.u32 %rd54, %r16;   // kW

    // Loop over input channels ic
    mov.u32 %r50, 0;                 // ic = 0
IC_LOOP:
    setp.ge.u32 %p2, %r50, %r11;
    @%p2 bra IC_END;

    // Loop over ky
    mov.u32 %r51, 0;                 // ky = 0
KY_LOOP:
    setp.ge.u32 %p3, %r51, %r15;
    @%p3 bra KY_END;

    // in_y = y_strided - pad_h + ky * dil_h
    mul.lo.s32 %r52, %r51, %r21;     // ky * dil_h
    add.s32    %r53, %r42, %r52;     // y_strided + ky*dil_h
    sub.s32    %r53, %r53, %r19;     // - pad_h

    // if (in_y < 0 || in_y >= H_in) continue ky
    setp.lt.s32 %p4, %r53, 0;
    @%p4 bra KY_CONT;
    setp.ge.s32 %p5, %r53, %r40;
    @%p5 bra KY_CONT;

    // Loop over kx
    mov.u32 %r54, 0;                 // kx = 0
KX_LOOP:
    setp.ge.u32 %p6, %r54, %r16;
    @%p6 bra KX_END;

    // in_x = x_strided - pad_w + kx * dil_w
    mul.lo.s32 %r55, %r54, %r22;     // kx * dil_w
    add.s32    %r56, %r43, %r55;     // x_strided + kx*dil_w
    sub.s32    %r56, %r56, %r20;     // - pad_w

    // if (in_x < 0 || in_x >= W_in) continue kx
    setp.lt.s32 %p7, %r56, 0;
    @%p7 bra KX_CONT;
    setp.ge.s32 %p8, %r56, %r41;
    @%p8 bra KX_CONT;

    // Compute input address index: (((n*C_in + ic)*H_in + in_y)*W_in + in_x)
    cvt.u64.u32 %rd60, %r32;           // n
    mul.lo.u64  %rd61, %rd60, %rd50;   // n*C_in
    cvt.u64.u32 %rd62, %r50;           // ic
    add.u64     %rd61, %rd61, %rd62;   // + ic
    mul.lo.u64  %rd63, %rd61, %rd51;   // * H_in
    cvt.u32.s32 %r57, %r53;            // in_y (u32)
    cvt.u64.u32 %rd64, %r57;
    add.u64     %rd63, %rd63, %rd64;   // + in_y
    mul.lo.u64  %rd65, %rd63, %rd52;   // * W_in
    cvt.u32.s32 %r58, %r56;            // in_x (u32)
    cvt.u64.u32 %rd66, %r58;
    add.u64     %rd67, %rd65, %rd66;   // + in_x
    mul.lo.u64  %rd68, %rd67, 4;       // * sizeof(float)
    add.u64     %rd69, %rd10, %rd68;   // x_ptr + offset

    // Compute weight address index: (((oc*C_in + ic)*kH + ky)*kW + kx)
    cvt.u64.u32 %rd70, %r34;           // oc
    mul.lo.u64  %rd71, %rd70, %rd50;   // oc*C_in
    add.u64     %rd71, %rd71, %rd62;   // + ic
    mul.lo.u64  %rd72, %rd71, %rd53;   // * kH
    cvt.u64.u32 %rd73, %r51;           // ky
    add.u64     %rd72, %rd72, %rd73;   // + ky
    mul.lo.u64  %rd74, %rd72, %rd54;   // * kW
    cvt.u64.u32 %rd75, %r54;           // kx
    add.u64     %rd76, %rd74, %rd75;   // + kx
    mul.lo.u64  %rd77, %rd76, 4;       // * sizeof(float)
    add.u64     %rd78, %rd11, %rd77;   // w_ptr + offset

    // Load and FMA
    ld.global.f32 %f1, [%rd69];
    ld.global.f32 %f2, [%rd78];
    fma.rn.f32    %f0, %f1, %f2, %f0;

KX_CONT:
    add.u32 %r54, %r54, 1;
    bra KX_LOOP;
KX_END:

KY_CONT:
    add.u32 %r51, %r51, 1;
    bra KY_LOOP;
KY_END:

    add.u32 %r50, %r50, 1;
    bra IC_LOOP;
IC_END:

    // Store result
    st.global.f32 [%rd39], %f0;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw_f32")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if not isinstance(kernel_size, int):
            raise ValueError("ModelNew expects an integer kernel_size")
        if not isinstance(stride, int) or not isinstance(padding, int) or not isinstance(dilation, int):
            raise ValueError("ModelNew expects integer stride, padding, and dilation")
        if groups != 1:
            raise NotImplementedError("ModelNew only supports groups=1")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        kH = kW = kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None

        # Initialize like torch.nn.Conv2d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = in_channels * kH * kW
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew supports only float32 inputs")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew requires contiguous input tensor")

        N, C_in, H_in, W_in = x.shape
        if C_in != self.in_channels:
            raise RuntimeError("Input channels do not match initialized in_channels")

        kH = kW = self.kernel_size
        sH = sW = self.stride
        pH = pW = self.padding
        dH = dW = self.dilation

        H_out = (H_in + 2 * pH - dH * (kH - 1) - 1) // sH + 1
        W_out = (W_in + 2 * pW - dW * (kW - 1) - 1) // sW + 1
        if H_out <= 0 or W_out <= 0:
            raise RuntimeError("Calculated output size is non-positive")

        y = torch.empty((N, self.out_channels, H_out, W_out), dtype=x.dtype, device=x.device)

        total = N * self.out_channels * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block

        module = _get_ptx_module()
        b_tensor = self.bias if self.bias is not None else self.weight  # valid device pointer, not dereferenced if no bias
        module.launch(
            "conv2d_nchw_f32",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[
                x,
                self.weight,
                b_tensor,
                y,
                u32(N),
                u32(C_in),
                u32(H_in),
                u32(W_in),
                u32(self.out_channels),
                u32(kH),
                u32(kW),
                u32(sH),
                u32(sW),
                u32(pH),
                u32(pW),
                u32(dH),
                u32(dW),
                u32(H_out),
                u32(W_out),
                u32(1 if self.bias is not None else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

